import java.io.BufferedInputStream;
import java.math.BigInteger;

public class Main {
    private static int nextInt(BufferedInputStream in) throws Exception {
        int c;
        do {
            c = in.read();
        } while (c <= ' ' && c != -1);

        int value = 0;
        while (c > ' ') {
            value = value * 10 + (c - '0');
            c = in.read();
        }
        return value;
    }

    public static void main(String[] args) throws Exception {
        BufferedInputStream in = new BufferedInputStream(System.in);
        int n = nextInt(in);

        StringBuilder digits = new StringBuilder(n);
        for (int i = 0; i < n; i++) {
            digits.append((char) ('0' + nextInt(in)));
        }

        String sequence = digits.toString();

        for (int length = 1; length <= n; length++) {
            if (sequence.charAt(0) == '0') {
                break;
            }

            BigInteger start = new BigInteger(sequence.substring(0, length));
            BigInteger current = start;
            int position = 0;
            boolean valid = true;

            while (position < n) {
                String number = current.toString();
                if (position + number.length() > n
                        || !sequence.regionMatches(position, number, 0, number.length())) {
                    valid = false;
                    break;
                }

                position += number.length();
                current = current.add(BigInteger.ONE);
            }

            if (valid) {
                System.out.println(start);
                return;
            }
        }
    }
}
